      "type": "claim",
      "quote": "Il Safety Office considera in modo globale la vigilanza sulla sicurezza sistemica al DATEC.",
      "gist": "The Safety Office globally oversees systemic safety at DATEC."
    },
    {
      "type": "claim",
      "quote": "Per garantire la sicurezza occorre tenere conto delle persone, delle tecnologie e delle strutture.",
      "gist": "To ensure safety, people, technologies, and structures must be considered."
    },
    {
      "type": "entity",
      "quote": "Safety Office",
      "gist": "Safety Office (a department or office)"
    },
    {
      "type": "entity",
      "quote": "DATEC",
      "gist": "DATEC (a department or organization)"
    },
    {
      "type": "obligation",
      "quote": "il Safety Office individua i temi da trattare, sviluppa soluzioni innovative insieme agli Uffici del DATEC, valuta i risultati in base ai requisiti definiti e adegua la vigilanza sulla sicurezza del DATEC in base alla visione definita.",
      "gist": "The Safety Office must identify topics, develop innovative solutions with DATEC offices, evaluate results against defined requirements, and adjust safety oversight based on the defined vision."
    },
    {
      "type": "entity",
      "quote": "Missione",
      "gist": "Mission (section title)"
    },
    {
      "type": "claim",
      "quote": "Il Safety Office, nella sua funzione di piattaforma di coordinamento, di consulenza e di apprendimento del Dipartimento, attiva i punti di forza della vigilanza sulla sicurezza al DATEC.",
      "gist": "The Safety Office, as a coordination, consulting, and learning platform for the Department, activates the strengths of safety oversight at DATEC."
    }
  ]
